target = root / 'docs/user-shadow/conversations/2026-11-19.md'
evidence = root / 'docs/user-shadow/evidence'
evidence.mkdir(parents=True, exist_ok=True)

def kind(p):
    try:
        mode = p.lstat().st_mode
    except FileNotFoundError:
        return 'missing'
    if stat.S_ISLNK(mode): return 'symlink'
    if stat.S_ISDIR(mode): return 'directory'
    if stat.S_ISREG(mode): return 'regular_file'
    return 'other'

def snapshot(p):
    entries = []
    def walk(d):
        for child in sorted(d.iterdir(), key=lambda x: x.name):
            k = kind(child)
            row = {'relative_path': str(child.relative_to(p)), 'type': k}
            if k == 'regular_file':
                data = child.read_bytes()
                row.update(size_bytes=len(data), sha256=hashlib.sha256(data).hexdigest(), content_base64=base64.b64encode(data).decode('ascii'))
            elif k == 'symlink':
                row['link_target'] = os.readlink(child)
            entries.append(row)
            if k == 'directory': walk(child)
    if kind(p) == 'directory': walk(p)
    return entries

def read_result(p):
    try:
        text = p.read_text(encoding='utf-8')
        return {'success': True, 'characters': len(text), 'sha256': hashlib.sha256(text.encode()).hexdigest()}
    except Exception as exc:
        return {'success': False, 'exception_type': type(exc).__name__, 'exception': str(exc), 'errno': getattr(exc, 'errno', None)}

